function filterEvents(events,filters){
 const [from,to]=dateRange(filters.period,filters.customDate),query=filters.query.trim().toLocaleLowerCase('nb-NO');
 return events.filter(event=>canSee(event,USER.id,filters.invitations)&&filters.interests.has(event.category)&&event.start.slice(0,10)>=from&&event.start.slice(0,10)<to&&(!query||[event.title,event.venue,event.description,event.organizer,categoryOf(event).name].join(' ').toLocaleLowerCase('nb-NO').includes(query))).sort((a,b)=>a.start.localeCompare(b.start)||a.title.localeCompare(b.title,'nb'));
}
function chipHTML(category){return `<button class="chip" style="--category:${category.color}" data-category="${category.id}" aria-pressed="${state.interests.has(category.id)}"><span class="dot"></span>${esc(category.name)}</button>`;}
function renderInterests(){
 $('#interests').innerHTML=CATEGORIES.map(chipHTML).join('');
 const selected=CATEGORIES.filter(category=>state.interests.has(category.id)),names=selected.slice(0,2).map(category=>category.name);
 $('#interest-summary').textContent=!selected.length?'Ingen valgt ennå':selected.length<=2?names.join(' · '):`${names.join(' · ')} +${selected.length-2}`;
 $('#interest-toggle').textContent=selected.length?'Endre':'Velg';
 $('#select-all').textContent=state.interests.size===CATEGORIES.length?'Nullstill':'Velg alle';
 document.querySelectorAll('[data-time]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.time===state.period));
 if($('#profile-dialog').open)renderProfile();
}
function renderList(events,filters){
 const hasInterests=filters.interests.size>0;
 $('#result-count').textContent=hasInterests?`${events.length} ${events.length===1?'event':'events'} i nærheten`:'Ditt Oslo starter her';
 const [from,to]=dateRange(filters.period,filters.customDate);
 $('#date-label').textContent=filters.period==='week'?'Neste 7 dager':from===plusDays(to,-1)?dateText(from):`${dateText(from)} – ${dateText(plusDays(to,-1))}`;
 if(!hasInterests){$('#event-list').innerHTML=`<div class="empty"><div class="empty-icon">${icon('sliders')}</div><h2>Velg noen interesser for å se hva som skjer</h2><p>Jazz på et hjørne? Et nytt bruktfunn?<br>Du bestemmer hva som dukker opp.</p></div>`;return;}
 if(!events.length){$('#event-list').innerHTML=`<div class="empty"><div class="empty-icon">${icon('search')}</div><h2>Ingen treff akkurat her</h2><p>Prøv en annen dag, flere interesser eller et annet søkeord.</p>${filters.query?'<button class="secondary" id="clear-search" style="margin-top:15px">Tøm søket</button>':''}</div>`;return;}
 $('#event-list').innerHTML=events.map(event=>{const c=categoryOf(event),capacity=event.capacity?` · ${event.attendees}/${event.capacity} plasser`:'',external=event.registrationType==='external'?'<span class="event-registration-badge">Ekstern påmelding</span>':'';return `<button class="event-card${filters.selected===event.id?' active':''}" data-event="${event.id}" aria-label="Åpne ${esc(event.title)}"><span class="event-card-layout"><img class="event-card-image" src="${eventImageURL(event)}" alt="" width="176" height="176" loading="lazy"><span class="event-card-content"><span class="eyebrow" style="--category:${c.color}"><span class="dot"></span>${esc(c.name)}${external}</span><span class="event-card-title">${esc(event.title)}</span><span class="event-card-description">${esc(event.description)}</span><span class="event-meta">${dayLabel(event)} · ${timeText(event)}</span><span class="event-meta">${esc(event.venue)}</span><span class="event-foot"><span>${event.distance.replace('.',',')} km${capacity} · <span class="privacy">${event.visibility==='private'?icon('lock')+'Privat':'Offentlig'}</span></span><span>Se mer →</span></span></span></span></button>`;}).join('');
}
let map=null,markerLayer=null,draftMarker=null,tileLayer=null;const markers=new Map();
function popupHTML(event){const c=categoryOf(event),places=event.capacity?`${event.attendees}/${event.capacity} plasser`:event.distance.replace('.',',')+' km';return `<article class="popup"><img class="popup-image" src="${eventImageURL(event)}" alt="Bilde for ${esc(event.title)}" width="800" height="450"><div class="eyebrow" style="--category:${c.color}"><span class="dot"></span>${esc(c.name)}${event.visibility==='private'?' · '+icon('lock')+' Privat':''}</div><h2>${esc(event.title)}</h2><div class="event-meta">${icon('clock')}${dayLabel(event)} · ${timeText(event)}</div><div class="event-meta">${icon('pin')}${esc(event.venue)}</div><div class="popup-stats"><strong>${esc(event.price)}</strong><span>${places}</span></div><div class="popup-actions"><button class="primary" data-open-event="${event.id}">Åpne arrangement${icon('arrow')}</button></div></article>`;}
function canReadComments(event){return event.visibility==='public'||event.creatorId===USER.id||state.invitations[event.id]==='accepted';}
function canWriteComments(event){return Boolean(currentSession)&&canReadComments(event);}
function eventCommentsSectionHTML(event){if(!canReadComments(event))return `<section class="event-comments"><div class="event-comments-heading"><h2>Kommentarer</h2></div><p class="subtle">Kommentarene blir tilgjengelige når du godtar invitasjonen.</p></section>`;return `<section class="event-comments"><div class="event-comments-heading"><h2>Kommentarer</h2><span id="event-comment-count"></span></div><div class="event-comment-list" id="event-comment-list"><p class="subtle">Laster kommentarer …</p></div>${canWriteComments(event)?`<form class="event-comment-form" id="event-comment-form" data-comment-event="${event.id}"><label for="event-comment-body">Skriv en kommentar</label><textarea id="event-comment-body" name="comment" maxlength="500" required placeholder="Spør om noe eller del en oppdatering …"></textarea><div><small>Maks 500 tegn</small><button class="primary" type="submit">Publiser</button></div></form>`:`<div class="event-comment-login"><p>Logg inn for å delta i samtalen.</p><button class="secondary" type="button" data-comment-login>Logg inn</button></div>`}</section>`;}
const commentTime=value=>new Intl.DateTimeFormat('nb-NO',{timeZone:'Europe/Oslo',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(value));
function renderEventComments(eventId){const list=$('#event-comment-list');if(!list||state.selected!==eventId)return;const comments=eventComments.get(eventId),event=state.events.find(item=>item.id===eventId);if(!comments){list.innerHTML='<p class="subtle">Laster kommentarer …</p>';return;}$('#event-comment-count').textContent=comments.length?`${comments.length}`:'';list.innerHTML=comments.map(comment=>{const name=comment.first_name||'Appventure-bruker',avatar=comment.avatar_path?publicAvatarURL(comment.avatar_path):avatarURL(comment.author_id),isOrganizer=comment.author_id===event?.creatorId;return `<article class="event-comment${isOrganizer?' organizer-comment':''}"><img src="${esc(avatar)}" alt="Profilbilde for ${esc(name)}" width="36" height="36"><div><header><strong>${esc(name)}</strong>${isOrganizer?'<span class="comment-organizer-badge">Arrangør</span>':''}<time datetime="${esc(comment.created_at)}">${esc(commentTime(comment.created_at))}</time>${comment.can_delete?`<button class="textbutton" type="button" data-delete-comment="${comment.id}" aria-label="Slett kommentaren fra ${esc(name)}">Slett</button>`:''}</header><p>${esc(comment.body)}</p></div></article>`;}).join('')||'<div class="event-comment-empty"><p>Ingen kommentarer ennå.</p><small>Start samtalen om arrangementet.</small></div>';}
async function loadEventComments(event){if(!canReadComments(event))return;const {data,error}=await supabase.rpc('get_event_comments',{requested_event_id:event.id});if(error){console.error(error);const list=$('#event-comment-list');if(list&&state.selected===event.id)list.innerHTML='<p class="subtle">Kommentarene kunne ikke lastes akkurat nå.</p>';return;}eventComments.set(event.id,data||[]);renderEventComments(event.id);}
function publicRegistrationHTML(event){const saved=state.saved.has(event.id),saveButton=`<button class="secondary save-event-button${saved?' saved':''}" data-save-event="${event.id}">${saved?icon('check'):''}${saved?'Lagret':'Lagre'}</button>`;if(event.registrationType==='external')return `<div class="external-registration-note"><strong>Ekstern påmelding</strong><span>Påmeldingen gjennomføres hos arrangøren.</span></div><a class="primary external-registration-link" href="${esc(event.externalRegistrationUrl)}" target="_blank" rel="noopener noreferrer">Gå til påmelding <span aria-hidden="true">↗</span></a>${saveButton}`;if(event.registrationType==='none')return `<p class="attendance-status">Ingen påmelding er nødvendig.</p>${saveButton}`;const attending=state.going.has(event.id),waitlisted=state.waitlisted.has(event.id),full=event.capacity&&event.attendees>=event.capacity,attendanceLabel=attending?'Meld meg av':waitlisted?'Forlat ventelisten':full?'Sett meg på venteliste':'Meld meg på',attendanceIcon=attending?icon('check'):'',placeLabel=event.capacity?`${event.attendees} av ${event.capacity} plasser`:`${event.attendees} ${event.attendees===1?'påmeldt':'påmeldte'}`,statusMessage=attending?'Du er påmeldt.':waitlisted?'Du står på ventelisten. Du flyttes automatisk inn når det blir ledig plass.':full?'Arrangementet er fullt. Du kan sette deg på ventelisten.':'';return `<button class="primary" data-going="${event.id}">${attendanceIcon}${attendanceLabel}</button>${statusMessage?`<p class="attendance-status${waitlisted?' waitlisted':''}">${statusMessage}</p>`:''}<button class="secondary" data-participants="${event.id}">${icon('people')}${placeLabel}${event.waitlist?` · ${event.waitlist} i kø`:''}</button>${saveButton}`;}
function eventDetailHTML(event){const c=categoryOf(event),owner=currentSession&&event.creatorId===USER.id,inviteStatus=state.invitations[event.id],acceptedInvite=inviteStatus==='accepted',mapAvailable=event.visibility==='public'||owner||acceptedInvite,privateActions=owner?'<p class="subtle">Dette er ditt private arrangement.</p>':acceptedInvite?`<p class="attendance-status">Du har godtatt invitasjonen.</p><button class="secondary" data-leave-invitation="${event.id}">Meld meg av</button>`:inviteStatus==='pending'?`<p class="subtle">Du er invitert til dette arrangementet.</p><button class="primary" data-accept="${event.id}">Godta invitasjonen</button><button class="secondary" data-decline="${event.id}">Avslå</button>`:inviteStatus==='declined'?`<p class="attendance-status declined">Du har avslått invitasjonen.</p><button class="primary" data-accept="${event.id}">Godta likevel</button>`:'<p class="subtle">Dette er et privat arrangement for inviterte deltakere.</p>',registrationBadge=event.registrationType==='external'?'<span class="event-registration-badge">Ekstern påmelding</span>':'';return `<article class="event-detail"><div class="event-detail-hero"><img src="${eventImageURL(event)}" alt="Bilde for ${esc(event.title)}" width="1200" height="675"><button class="event-detail-close" data-close="event-detail-dialog" aria-label="Lukk arrangementet">${icon('close')}</button></div><div class="event-detail-body"><section class="event-detail-main"><div class="eyebrow" style="--category:${c.color}"><span class="dot"></span>${esc(c.name)}${event.visibility==='private'?' · '+icon('lock')+' Privat':' · Offentlig'}${registrationBadge}</div><h1 id="event-detail-title">${esc(event.title)}</h1><div class="event-detail-facts"><div>${icon('clock')}<span><strong>${dayLabel(event)}</strong><small>${timeText(event)}</small></span></div><div>${icon('pin')}<span><strong>${esc(event.venue)}</strong><small>${event.distance.replace('.',',')} km unna</small></span></div><div><span class="event-detail-price">${esc(event.price)}</span></div></div><section class="event-detail-description"><h2>Om arrangementet</h2><p>${esc(event.description)}</p></section><div class="event-detail-organizer"><span class="event-detail-organizer-avatar">${esc((event.organizer||'A').slice(0,1).toUpperCase())}</span><span><small>Arrangør</small><strong>${esc(event.organizer)}</strong></span></div></section><aside class="event-detail-actions"><h2>Bli med</h2>${event.visibility==='public'?publicRegistrationHTML(event):privateActions}${mapAvailable?`<button class="secondary" data-show-map="${event.id}">${icon('pin')}Vis i kart</button>`:''}<button class="secondary" data-share="${event.id}">${icon('share')}Del arrangement</button>${owner&&event.visibility==='private'?`<button class="secondary" data-invite="${event.id}">${icon('people')}Inviter</button>`:''}${owner?`<div class="event-detail-owner"><span class="section-label">For arrangøren</span><button class="secondary" data-edit-event="${event.id}">${icon('edit')}Rediger</button><button class="textbutton danger-link" data-delete-event="${event.id}">Slett arrangement</button></div>`:''}</aside></div></article>`;}
function renderEventDetail(event){$('#event-detail-content').innerHTML=eventDetailHTML(event);$('.event-detail-organizer')?.insertAdjacentHTML('beforebegin',eventCommentsSectionHTML(event));renderEventComments(event.id);}
function openEventDetail(event,updateURL=true,fromProfile=false){if(!event||!canAccessEvent(event))return;state.selected=event.id;renderList(filterEvents(state.events,state),state);renderMap(filterEvents(state.events,state),state);renderEventDetail(event);const dialog=$('#event-detail-dialog');dialog.classList.toggle('profile-context',fromProfile);$('#profile-dialog').classList.toggle('event-open',fromProfile);if(!dialog.open)dialog.showModal();loadEventComments(event);if(updateURL){const url=new URL(location.href);url.hash=`event=${encodeURIComponent(event.id)}`;history.replaceState(null,'',url);}}
function renderMap(events,filters){
 $('#map-help').hidden=filters.interests.size>0;
 $('#map-count').hidden=filters.interests.size===0;
 $('#map-count').innerHTML=icon('pin')+`${events.length} ${events.length===1?'event':'events'} på kartet`;
 if(!map)return;
 const openId=[...markers].find(([,m])=>m.isPopupOpen())?.[0];
 markerLayer.clearLayers();markers.clear();
 for(const event of events){const c=categoryOf(event);const marker=L.marker([event.lat,event.lng],{title:event.title,alt:event.title,icon:L.divIcon({className:'map-pin',html:`<div class="pin-core${filters.selected===event.id?' selected':''}" style="--category:${c.color}"><span>${event.visibility==='private'?icon('lock'):'·'}</span></div>`,iconSize:[30,36],iconAnchor:[15,33],popupAnchor:[0,-30]})}).bindPopup(popupHTML(event),{maxWidth:305,autoPanPaddingTopLeft:L.point(25,110),autoPanPaddingBottomRight:L.point(25,45)}).addTo(markerLayer);
 marker.on('click',()=>{state.selected=event.id;renderList(filterEvents(state.events,state),state);});markers.set(event.id,marker);
 }
 if(openId&&markers.has(openId))markers.get(openId).openPopup();
}
function render(){const events=filterEvents(state.events,state);renderInterests();renderList(events,state);renderMap(events,state);const pending=currentSession?Object.values(state.invitations).filter(v=>v==='pending').length:0;$('#invite-badge').textContent='!';$('#invite-badge').hidden=!pending;}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3600);}
function authErrorMessage(error){if(!error)return 'Noe gikk galt. Prøv igjen.';if(error.message?.includes('Invalid login credentials'))return 'Feil e-post eller passord.';if(error.message?.includes('already registered'))return 'Kunne ikke opprette konto med disse opplysningene. Prøv å logge inn eller bruke glemt passord.';if(error.message?.includes('Email not confirmed'))return 'Bekreft e-postadressen før du logger inn.';return error.message||'Noe gikk galt. Prøv igjen.';}
function eventErrorMessage(error){if(error?.message?.includes('Capacity cannot be lower'))return 'Antall plasser kan ikke være lavere enn antallet som allerede er påmeldt.';if(error?.message?.includes('Remove attendees before changing'))return 'Påmeldte deltakere må fjernes før du kan bytte til ekstern eller ingen påmelding.';if(error?.code==='42501')return 'Du har ikke tilgang til å lagre arrangementet (42501).';if(error?.code==='23503')return 'Arrangementet kunne ikke kobles til profilen din (23503).';if(error?.code==='23514')return 'Dato, klokkeslett eller et annet felt er ugyldig (23514).';if(error?.code==='PGRST204'||error?.code==='42703')return 'Databaseskjemaet mangler en nødvendig oppdatering.';return `${error?.message||'Ukjent feil'}${error?.code?` (${error.code})`:''}`;}
function showAuthMessage(message,isError=false){const element=$('#auth-message');element.textContent=message;element.hidden=!message;element.classList.toggle('error',isError);}
function setAuthMode(mode){authMode=mode;const signup=mode==='signup',form=$('#auth-form'),submit=form.querySelector('.auth-submit');$('#auth-title').textContent=signup?'Opprett profil':'Logg inn';$('#auth-signup-fields').hidden=!signup;$('#auth-signup-confirmations').hidden=!signup;form.elements.firstName.required=signup;form.elements.lastName.required=signup;form.elements.district.required=signup;form.elements.passwordConfirm.required=signup;form.elements.termsAccepted.required=signup;form.elements.ageConfirmed.required=signup;form.elements.password.autocomplete=signup?'new-password':'current-password';submit.textContent=signup?'Opprett profil':'Logg inn';submit.hidden=false;$('#forgot-password').hidden=signup;$('#resend-confirmation').hidden=true;form.querySelectorAll('.password-input input').forEach(input=>input.type='password');form.querySelectorAll('.password-toggle').forEach(button=>{button.textContent='Vis';button.setAttribute('aria-label','Vis passord');});document.querySelectorAll('[data-auth-mode]').forEach(button=>button.setAttribute('aria-selected',String(button.dataset.authMode===mode)));updatePasswordFeedback();showAuthMessage('');}
function updatePasswordFeedback(){
 const form=$('#auth-form'),signup=authMode==='signup',password=form.elements.password,confirmation=form.elements.passwordConfirm;
 const lengthOK=password.value.length>=10,match=confirmation.value.length>0&&confirmation.value===password.value;
 password.minLength=signup?10:1;
 confirmation.disabled=!signup;
 for(const [input,id,valid,message] of [
  [password,'signup-password-feedback',lengthOK,lengthOK?'Minst 10 tegn – oppfylt':'Minst 10 tegn. Bruk gjerne en unik passfrase.'],
  [confirmation,'signup-confirmation-feedback',match,match?'Passordene er like':confirmation.value?'Passordene er ikke like ennå.':'Gjenta passordet.']
 ]){
  let feedback=$('#'+id);
  if(!feedback){
   feedback=document.createElement('span');feedback.id=id;feedback.setAttribute('aria-live','polite');
   input.closest('.field').append(feedback);input.setAttribute('aria-describedby',id);
  }
  feedback.hidden=!signup;feedback.className='password-feedback'+(valid?' is-valid':'');
  feedback.innerHTML=(valid?icon('check'):'')+esc(message);
  input.classList.toggle('password-valid',signup&&valid);
 }
 password.closest('.field').querySelector('.field-help').hidden=true;
}
function openAuthDialog(mode='login'){setAuthMode(mode);$('#auth-dialog').showModal();}
function invitationURL(token){const url=new URL(location.href);url.hash='';url.searchParams.set('invite',token);return url.href;}
async function claimPendingInvitation(){if(!pendingInvitationToken||!currentSession)return null;const {data,error}=await supabase.rpc('claim_event_invitation',{invitation_token:pendingInvitationToken});if(error){console.error(error);toast(error.code==='42501'?'Logg inn med e-postadressen invitasjonen ble sendt til.':'Invitasjonslenken er ugyldig eller utløpt.');return null;}pendingInvitationToken=null;const cleanURL=new URL(location.href);cleanURL.searchParams.delete('invite');history.replaceState(null,'',cleanURL);toast('Invitasjonen er lagt til på profilen din.');return data;}
async function showInvitationPreview(){if(!pendingInvitationToken||currentSession)return;const {data,error}=await supabase.rpc('preview_event_invitation',{invitation_token:pendingInvitationToken});if(error||!data?.length){toast('Invitasjonslenken er ugyldig eller utløpt.');return;}const invitation=data[0];openAuthDialog('signup');showAuthMessage(`${invitation.inviter_name||'En Appventure-bruker'} inviterer deg til «${invitation.event_title}». Opprett konto eller logg inn med e-postadressen invitasjonen ble sendt til.`);}
function resetUser(){USER.id=null;USER.email='';USER.firstName='';USER.lastName='';USER.district='';USER.avatarPath=null;USER.customAvatar='';state.interests=new Set();state.going=new Set();state.waitlisted=new Set();state.saved=new Set();state.invitations={};state.friends=[];state.friendRequests=[];updateAvatarUI();render();}
async function loadProfile(session){
 const metadata=session.user.user_metadata||{};
 let {data:profile,error}=await supabase.from('profiles').select('id, first_name, last_name, district, avatar_path, interests').eq('id',session.user.id).maybeSingle();
 if(error)throw error;
 if(!profile){const fallback={id:session.user.id,first_name:metadata.first_name||null,last_name:metadata.last_name||null,district:metadata.district||null};const result=await supabase.from('profiles').upsert(fallback).select('id, first_name, last_name, district, avatar_path, interests').single();if(result.error)throw result.error;profile=result.data;}
 USER.id=session.user.id;USER.email=session.user.email||'';USER.firstName=profile.first_name||metadata.first_name||'';USER.lastName=profile.last_name||metadata.last_name||'';USER.district=profile.district||metadata.district||'';USER.avatarPath=profile.avatar_path||null;USER.customAvatar=publicAvatarURL(USER.avatarPath);state.interests=new Set((profile.interests||[]).filter(id=>CATEGORIES.some(category=>category.id===id)));updateAvatarUI();render();
}
async function loadSocial(){const [friendships,requests]=await Promise.all([supabase.from('friendships').select('user_a, user_b, created_at'),supabase.from('friend_requests').select('id, sender_id, created_at').eq('receiver_id',USER.id).eq('status','pending').order('created_at',{ascending:false})]);if(friendships.error)throw friendships.error;if(requests.error)throw requests.error;const friendIds=friendships.data.map(row=>row.user_a===USER.id?row.user_b:row.user_a),requesterIds=requests.data.map(row=>row.sender_id),profileIds=[...new Set([...friendIds,...requesterIds])];let profiles=[];if(profileIds.length){const result=await supabase.from('profiles').select('id, first_name, last_name, district, avatar_path').in('id',profileIds);if(result.error)throw result.error;profiles=result.data;}const byId=new Map(profiles.map(profile=>[profile.id,profile]));const person=profile=>({id:profile.id,name:[profile.first_name,profile.last_name].filter(Boolean).join(' ')||'Appventure-bruker',district:profile.district||'',avatar:publicAvatarURL(profile.avatar_path)});state.friends=friendIds.map(id=>byId.get(id)).filter(Boolean).map(person);state.friendRequests=requests.data.map(request=>{const profile=byId.get(request.sender_id);return profile?{...person(profile),requestId:request.id}:null;}).filter(Boolean);}
async function applySession(session){currentSession=session;eventComments.clear();if(!session){resetUser();await loadEvents();return;}try{await loadProfile(session);await loadSocial();await claimPendingInvitation();await loadEvents();if($('#event-detail-dialog').open){const event=state.events.find(item=>item.id===state.selected);if(event){renderEventDetail(event);loadEventComments(event);}}}catch(error){console.error(error);toast('Kunne ikke hente profilen. Prøv å laste siden på nytt.');}}
async function initializeAuth(){if(!hasSupabaseConfig){toast('Supabase er ikke konfigurert.');return;}supabase.auth.onAuthStateChange((event,session)=>{window.setTimeout(async()=>{await applySession(session);if(event==='PASSWORD_RECOVERY'&&!$('#password-update-dialog').open){$('#password-update-form').reset();$('#password-update-message').hidden=true;$('#password-update-dialog').showModal();}},0);});const {data,error}=await supabase.auth.getSession();if(error){toast('Kunne ikke kontrollere innloggingen.');return;}await applySession(data.session);if(!data.session)await showInvitationPreview();}
function scheduleInterestSave(){if(!currentSession)return;clearTimeout(interestSaveTimer);interestSaveTimer=setTimeout(async()=>{const {error}=await supabase.from('profiles').update({interests:[...state.interests]}).eq('id',USER.id);if(error)toast('Kunne ikke lagre interessene dine.');},450);}
function setMobileView(view){const showMap=view==='map';$('.app').classList.toggle('mobile-map-visible',showMap);$('#mobile-map-open').setAttribute('aria-pressed',String(showMap));$('#mobile-list-open').setAttribute('aria-pressed',String(!showMap));if(showMap&&map)requestAnimationFrame(()=>{map.invalidateSize();if(state.selected&&markers.has(state.selected)){const event=state.events.find(item=>item.id===state.selected);if(event)map.setView([event.lat,event.lng],15,{animate:false});markers.get(state.selected).openPopup();}});}
function focusEvent(id){const event=state.events.find(e=>e.id===id);if(!event||!canSee(event))return;state.selected=id;renderList(filterEvents(state.events,state),state);if(map&&markers.has(id)){if(innerWidth<=720)setMobileView('map');else{map.setView([event.lat,event.lng],15,{animate:false});markers.get(id).openPopup();}}else if(!map){$('#invite-event-name').textContent='';toast('Kartet kunne ikke lastes. Sjekk internettforbindelsen.');}}
function revealEvent(event){if(!event)return;state.interests.add(event.category);state.query='';$('#search').value='';if(event.start.startsWith(TODAY))state.period='today';else if(event.start.startsWith(plusDays(TODAY,1)))state.period='tomorrow';else {const day=event.start.slice(0,10);if(day>=weekendStart&&day<weekendEnd)state.period='weekend';else if(day>=TODAY&&day<plusDays(TODAY,7))state.period='week';else {state.period='custom';state.customDate=day;}}render();openEventDetail(event);}
function friendHTML(friend,type,checked=false){return `<label class="friend"><input type="checkbox" name="${type}" value="${friend.id}" ${checked?'checked':''}>${avatarImage(friend.avatarSeed,friend.name,'friend-avatar')}${esc(friend.name)}<small>Venn</small></label>`;}
let profileTab='events',profileEventFilter='all',profilePastOpen=false,profileInterestsOpen=false;
function profileTabsHTML(){const pending=Object.values(state.invitations).filter(status=>status==='pending').length;return `<div class="profile-tabs" role="tablist" aria-label="Min side"><button class="profile-tab" type="button" role="tab" data-profile-tab="events" aria-selected="${profileTab==='events'}">Arrangementer</button><button class="profile-tab" type="button" role="tab" data-profile-tab="invitations" aria-selected="${profileTab==='invitations'}">Invitasjoner${pending?` <span class="profile-tab-badge">${pending}</span>`:''}</button><button class="profile-tab" type="button" role="tab" data-profile-tab="friends" aria-selected="${profileTab==='friends'}">Venner${state.friendRequests.length?` <span class="profile-tab-badge">${state.friendRequests.length}</span>`:''}</button><button class="profile-tab" type="button" role="tab" data-profile-tab="profile" aria-selected="${profileTab==='profile'}">Profil</button></div>`;}
function socialAvatar(person){return person.avatar?`<img class="friend-avatar" src="${esc(person.avatar)}" alt="Profilbilde for ${esc(person.name)}" width="48" height="48">`:avatarImage(person.id,person.name,'friend-avatar');}
function profileFriendsHTML(){const requests=state.friendRequests.map(person=>`<div class="profile-friend">${socialAvatar(person)}<div class="profile-friend-copy"><strong>${esc(person.name)}</strong><small>${esc(person.district||'Vil bli venn')}</small></div><div class="friend-request-actions"><button class="primary" data-friend-accept="${person.requestId}">Godta</button><button class="secondary" data-friend-decline="${person.requestId}">Avslå</button></div></div>`).join(''),friends=state.friends.map(person=>`<div class="profile-friend">${socialAvatar(person)}<div class="profile-friend-copy"><strong>${esc(person.name)}</strong><small>${esc(person.district||'Appventure-venn')}</small></div><button class="textbutton" data-remove-friend="${person.id}">Fjern</button></div>`).join('');return `<section role="tabpanel" aria-label="Venner"><div class="profile-friends-head"><h3>Mine venner</h3><span class="subtle">${state.friends.length} venner</span></div><form class="friend-add-form" id="friend-request-form"><label class="field">Legg til med e-post<input name="email" type="email" required autocomplete="email" placeholder="venn@eksempel.no"></label><button class="secondary" type="submit">Send venneforespørsel</button><p class="field-help">Vi avslører ikke om adressen er registrert.</p></form>${requests?`<section class="profile-section"><h3>Venneforespørsler</h3>${requests}</section>`:''}<section class="profile-section"><h3>Venneliste</h3>${friends||'<p class="subtle">Du har ikke lagt til noen venner ennå.</p>'}</section></section>`;}
function profileHeaderHTML(){return `<div class="profile-person profile-person-compact"><div class="profile-avatar-wrap">${userAvatarImage('profile-avatar')}<button class="profile-avatar-edit" type="button" data-edit-profile aria-label="Rediger profil">${icon('edit')}</button></div><div><h3>${esc(USER.name)}</h3><p>${esc(USER.district||'Legg til bosted')}</p></div></div>`;}
function profileEventRole(event){if(event.creatorId===USER.id)return {id:'hosting',label:'Arrangør'};if(state.waitlisted.has(event.id))return {id:'waitlist',label:'Venteliste'};if(state.going.has(event.id)||state.invitations[event.id]==='accepted')return {id:'attending',label:'Påmeldt'};if(state.saved.has(event.id))return {id:'saved',label:'Lagret'};return {id:'invited',label:'Invitert'};}
function profileEventCardHTML(event,isPast=false){const role=profileEventRole(event),date=event.start.slice(0,10),day=dateText(date,{day:'2-digit'}),month=dateText(date,{month:'short'}).replace('.','');return `<button class="profile-event-card${isPast?' past':''}" data-profile-event="${event.id}"><span class="profile-event-date"><strong>${day}</strong><small>${esc(month)}</small></span><span class="profile-event-copy"><span class="profile-event-top"><span class="profile-event-role ${role.id}">${esc(isPast&&role.id==='attending'?'Deltok':role.label)}</span>${event.visibility==='private'?`<span class="profile-event-private">${icon('lock')}Privat</span>`:''}</span><strong>${esc(event.title)}</strong><small>${timeText(event)} · ${esc(event.venue)}</small></span><span class="profile-event-arrow" aria-hidden="true">→</span></button>`;}
function profileEventsHTML(){const now=osloLocalDateTime(new Date().toISOString()),related=state.events.filter(event=>event.creatorId===USER.id||state.going.has(event.id)||state.waitlisted.has(event.id)||state.invitations[event.id]==='accepted'||state.saved.has(event.id)),matchesFilter=event=>profileEventFilter==='all'||(profileEventFilter==='saved'?state.saved.has(event.id):profileEventRole(event).id===profileEventFilter),upcoming=related.filter(event=>event.end>=now&&matchesFilter(event)).sort((a,b)=>a.start.localeCompare(b.start)),past=related.filter(event=>event.end<now&&matchesFilter(event)).sort((a,b)=>b.start.localeCompare(a.start)),filters=[['all','Alle'],['attending','Påmeldt'],['saved','Lagret'],['hosting','Arrangerer'],['waitlist','Venteliste']].map(([id,label])=>`<button type="button" data-profile-event-filter="${id}" aria-pressed="${profileEventFilter===id}">${label}</button>`).join('');return `<section role="tabpanel" aria-label="Arrangementer"><div class="profile-event-filters" aria-label="Filtrer arrangementer">${filters}</div><section class="profile-event-section"><div class="profile-section-heading"><h3>Kommende</h3><span>${upcoming.length}</span></div><div class="profile-event-list">${upcoming.map(event=>profileEventCardHTML(event)).join('')||'<div class="profile-empty"><p>Ingen kommende arrangementer i denne kategorien.</p><button class="textbutton" data-close="profile-dialog">Finn noe å gjøre →</button></div>'}</div></section>${past.length?`<section class="profile-past-section"><button class="profile-accordion-trigger" type="button" data-profile-past-toggle aria-expanded="${profilePastOpen}"><span><strong>Tidligere arrangementer</strong><small>${past.length} arrangementer</small></span><span aria-hidden="true">${profilePastOpen?'−':'+'}</span></button>${profilePastOpen?`<div class="profile-event-list">${past.map(event=>profileEventCardHTML(event,true)).join('')}</div>`:''}</section>`:''}</section>`;}
function profileInvitationCardHTML(event,status){const labels={pending:'Venter på svar',accepted:'Godtatt',declined:'Avslått'},openLabel=status==='declined'?'Se arrangement og svar på nytt':'Se arrangement',actions=status==='pending'?`<button class="secondary profile-invitation-open" data-profile-event="${event.id}">${openLabel}</button><div class="invitation-actions"><button class="primary" data-accept="${event.id}">Godta</button><button class="secondary" data-decline="${event.id}">Avslå</button></div>`:`<button class="secondary profile-invitation-open" data-profile-event="${event.id}">${openLabel}</button>`;return `<div class="profile-invitation-card ${status}"><div class="profile-invitation-status">${labels[status]||'Invitasjon'}</div><div class="eyebrow">${icon('lock')}Fra ${esc(event.organizer)}</div><h3>${esc(event.title)}</h3><p>${dayLabel(event)} · ${timeText(event)}<br>${esc(event.venue)}</p>${actions}</div>`;}
function profileInvitationsHTML(){const invitations=state.events.filter(event=>Object.hasOwn(state.invitations,event.id)).sort((a,b)=>a.start.localeCompare(b.start)),groups=[['pending','Nye invitasjoner'],['accepted','Godtatte'],['declined','Avslåtte']].map(([status,title])=>{const events=invitations.filter(event=>state.invitations[event.id]===status);return events.length?`<section class="profile-invitation-section"><div class="profile-section-heading"><h3>${title}</h3><span>${events.length}</span></div>${events.map(event=>profileInvitationCardHTML(event,status)).join('')}</section>`:'';}).join('');return `<section role="tabpanel" aria-label="Invitasjoner">${groups||'<div class="profile-empty"><p>Du har ingen invitasjoner ennå.</p></div>'}</section>`;}
function profileSettingsHTML(){const selected=CATEGORIES.filter(category=>state.interests.has(category.id)),summary=selected.length?`${selected.slice(0,2).map(category=>category.name).join(', ')}${selected.length>2?` +${selected.length-2}`:''}`:'Ingen interesser valgt';return `<section role="tabpanel" aria-label="Profil og interesser"><button class="secondary profile-edit-main" type="button" data-edit-profile>${icon('edit')}Rediger profil</button><section class="profile-settings-section"><button class="profile-accordion-trigger" type="button" data-profile-interests-toggle aria-expanded="${profileInterestsOpen}"><span><strong>Mine interesser</strong><small>${esc(summary)}</small></span><span aria-hidden="true">${profileInterestsOpen?'−':'+'}</span></button>${profileInterestsOpen?`<div class="profile-interest-content"><div class="chips">${CATEGORIES.map(chipHTML).join('')}</div><p class="field-help">Endringene lagres automatisk.</p></div>`:''}</section><section class="profile-account"><p class="subtle profile-email">Innlogget som ${esc(USER.email)}</p><div class="profile-account-actions"><button type="button" class="secondary" data-logout>Logg ut</button><button type="button" class="textbutton danger-link" data-delete-account>Slett konto</button></div></section></section>`;}
function renderProfile(){const content=profileTab==='invitations'?profileInvitationsHTML():profileTab==='friends'?profileFriendsHTML():profileTab==='profile'?profileSettingsHTML():profileEventsHTML();$('#profile-body').innerHTML=profileHeaderHTML()+profileTabsHTML()+content;}
let pendingAvatarFile=null,removeAvatar=false,avatarPreviewURL='';
function openProfileEditor(){const form=$('#profile-edit-form');form.elements.firstName.value=USER.firstName;form.elements.lastName.value=USER.lastName;form.elements.district.value=USER.district;$('#avatar-upload').value='';pendingAvatarFile=null;removeAvatar=false;if(avatarPreviewURL)URL.revokeObjectURL(avatarPreviewURL);avatarPreviewURL='';$('#avatar-preview').src=userAvatarURL();$('#avatar-remove').hidden=!USER.avatarPath;$('#profile-edit-dialog').showModal();}
function closeDialog(id){$('#'+id).close();}
function updateRegistrationFields(){const form=$('#event-form'),isPublic=form.elements.visibility.value==='public',type=isPublic?form.elements.registrationType.value:'internal',isInternal=type==='internal',isExternal=type==='external';if(!isPublic)form.elements.registrationType.value='internal';$('#registration-type-field').hidden=!isPublic;$('#external-registration-field').hidden=!isPublic||!isExternal;form.elements.externalRegistrationUrl.required=isPublic&&isExternal;$('#capacity-field').hidden=!isPublic||!isInternal;if(!isInternal)form.elements.capacity.value='';if(!isExternal)form.elements.externalRegistrationUrl.value='';}
function openCreate(){const form=$('#event-form');form.reset();form.elements.date.value=TODAY;form.elements.date.min=TODAY;state.editingEventId=null;state.draftLocation=null;state.draftImage=EVENT_IMAGES[0].src;state.draftImagePreset='green';state.draftExistingImagePath=null;state.draftRemoveImage=false;draftEventImageFile=null;$('#create-title').textContent='Noe på gang?';form.querySelector('[type="submit"]').firstChild.textContent='Opprett event';renderEventImagePresets();$('#event-image-preview').hidden=true;$('#event-image-preview').removeAttribute('src');$('#event-image-remove').hidden=true;if(draftMarker){draftMarker.remove();draftMarker=null;}$('#location-status').textContent='Ingen kartposisjon valgt.';$('#private-friends').hidden=true;updateRegistrationFields();$('#create-dialog').showModal();}
function openEditEvent(event){const form=$('#event-form');form.reset();state.editingEventId=event.id;state.draftLocation={lat:event.lat,lng:event.lng};state.draftImagePreset=event.imagePreset||'green';state.draftExistingImagePath=event.imagePath||null;state.draftRemoveImage=false;draftEventImageFile=null;state.draftImage=event.imagePath?event.image:(EVENT_IMAGES.find(image=>image.id===state.draftImagePreset)?.src||EVENT_IMAGES[0].src);form.elements.title.value=event.title;form.elements.category.value=event.category;form.elements.description.value=event.description;form.elements.date.value=event.start.slice(0,10);form.elements.date.min=TODAY;form.elements.price.value=event.price==='Gratis'?'':event.price;form.elements.start.value=event.start.slice(11,16);form.elements.end.value=event.end.slice(11,16);form.elements.venue.value=event.venue;form.elements.capacity.value=event.capacity||'';form.elements.visibility.value=event.visibility;form.elements.registrationType.value=event.registrationType||'internal';form.elements.externalRegistrationUrl.value=event.externalRegistrationUrl||'';$('#create-title').textContent='Rediger arrangement';form.querySelector('[type="submit"]').firstChild.textContent='Lagre endringer';renderEventImagePresets();$('#event-image-preview').hidden=!event.imagePath;$('#event-image-preview').src=event.imagePath?event.image:'';$('#event-image-remove').hidden=!event.imagePath;$('#location-status').textContent=`Kartpunkt valgt: ${event.lat.toFixed(4)}, ${event.lng.toFixed(4)}.`;$('#private-friends').hidden=event.visibility!=='private';updateRegistrationFields();$('#create-dialog').showModal();}
function stopPicking(){state.picking=false;$('.map-shell').classList.remove('picking');$('#pick-bar').hidden=true;if(draftMarker){draftMarker.remove();draftMarker=null;}if(innerWidth<=720)setMobileView('list');$('#create-dialog').showModal();if(state.draftLocation)$('#location-status').textContent=`Kartpunkt valgt: ${state.draftLocation.lat.toFixed(4)}, ${state.draftLocation.lng.toFixed(4)}.`;}
function initMap(){
 if(!window.L){$('#map-error').hidden=false;$('#map-error').textContent='Kartet kunne ikke lastes. Leaflet og kartflisene trenger internett. Filtre, profil og eventskjema fungerer fortsatt.';$('#pick-start').disabled=true;return;}
 map=L.map('map',{zoomControl:false,minZoom:11,maxZoom:18,maxBounds:[[59.78,10.48],[60.04,11.04]],maxBoundsViscosity:1}).setView(CENTER,13);
 tileLayer=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>',maxZoom:19}).addTo(map);
 let loadedTiles=0;tileLayer.on('tileload',()=>{loadedTiles++;$('#map-error').hidden=true;});tileLayer.on('tileerror',()=>{if(!loadedTiles){$('#map-error').hidden=false;$('#map-error').textContent='Kartflisene er ikke tilgjengelige akkurat nå. Sjekk internettforbindelsen. Markører og filtre fungerer fortsatt.';}});
 markerLayer=L.layerGroup().addTo(map);L.control.zoom({position:'bottomright',zoomInTitle:'Zoom inn',zoomOutTitle:'Zoom ut'}).addTo(map);
 map.on('click',e=>{if(!state.picking)return;state.draftLocation={lat:e.latlng.lat,lng:e.latlng.lng};if(draftMarker)draftMarker.setLatLng(e.latlng);else draftMarker=L.marker(e.latlng,{icon:L.divIcon({className:'map-pin',html:'<div class="pin-core" style="--category:#333"><span>+</span></div>',iconSize:[30,36],iconAnchor:[15,33]})}).addTo(map);$('#pick-done').disabled=false;$('#pick-instruction').textContent='Punkt valgt. Klikk et annet sted for å flytte det.';});
}
$('#today-label').textContent=dateText(TODAY,{weekday:'long',day:'numeric',month:'long'});
$('#category-select').innerHTML=CATEGORIES.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');
$('#search').addEventListener('input',e=>{state.query=e.target.value;render();});
$('#select-all').addEventListener('click',()=>{state.interests=state.interests.size===CATEGORIES.length?new Set():new Set(CATEGORIES.map(c=>c.id));render();scheduleInterestSave();});
$('#interest-toggle').addEventListener('click',()=>{const panel=$('#interest-panel'),willOpen=panel.hidden;panel.hidden=!willOpen;$('#interest-toggle').setAttribute('aria-expanded',String(willOpen));if(willOpen)panel.querySelector('.chip')?.focus();});
$('#interest-done').addEventListener('click',()=>{$('#interest-panel').hidden=true;$('#interest-toggle').setAttribute('aria-expanded','false');$('#interest-toggle').focus();});
$('#mobile-map-open').addEventListener('click',()=>setMobileView('map'));
$('#mobile-list-open').addEventListener('click',()=>setMobileView('list'));
$('#profile-open').addEventListener('click',async()=>{if(!currentSession){openAuthDialog();return;}try{await loadSocial()}catch(error){console.error(error);toast('Kunne ikke oppdatere vennelisten.');}renderProfile();$('#profile-dialog').showModal();});
$('#auth-form').addEventListener('submit',async e=>{e.preventDefault();if(!supabase)return;const form=e.target,values=new FormData(form),email=values.get('email').trim(),password=values.get('password'),submit=form.querySelector('.auth-submit');submit.disabled=true;showAuthMessage('');try{if(authMode==='signup'){const firstName=values.get('firstName').trim(),lastName=values.get('lastName').trim(),district=values.get('district').trim(),confirmation=values.get('passwordConfirm');if(!firstName||!lastName||!district){showAuthMessage('Fyll inn navn og bosted.',true);return;}if(password!==confirmation){showAuthMessage('Passordene er ikke like.',true);form.elements.passwordConfirm.focus();return;}if(!values.get('termsAccepted')||!values.get('ageConfirmed')){showAuthMessage('Du må godta brukervilkårene og bekrefte aldersgrensen.',true);return;}const redirectURL=pendingInvitationToken?invitationURL(pendingInvitationToken):location.origin;const {data,error}=await supabase.auth.signUp({email,password,options:{emailRedirectTo:redirectURL,data:{first_name:firstName,last_name:lastName,district,terms_version:TERMS_VERSION,privacy_version:PRIVACY_VERSION,minimum_age_confirmed:true}}});if(error)throw error;if(data.session){await applySession(data.session);closeDialog('auth-dialog');form.reset();toast('Profilen er opprettet.');}else{form.elements.password.value='';form.elements.passwordConfirm.value='';updatePasswordFeedback();submit.hidden=true;$('#resend-confirmation').hidden=false;showAuthMessage('Sjekk e-posten din og bekreft kontoen. Du kan lukke dette vinduet mens du venter.');}}else{const {data,error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error;await applySession(data.session);closeDialog('auth-dialog');form.reset();toast(`Velkommen, ${USER.firstName||'du'}!`);}}catch(error){if(error?.message?.includes('Email not confirmed'))$('#resend-confirmation').hidden=false;showAuthMessage(authErrorMessage(error),true);}finally{submit.disabled=false;}});
$('#auth-form').addEventListener('input',e=>{if(['password','passwordConfirm'].includes(e.target.name))updatePasswordFeedback();});
$('#auth-form').addEventListener('change',e=>{if(['password','passwordConfirm'].includes(e.target.name))updatePasswordFeedback();});
$('#auth-form').addEventListener('reset',()=>queueMicrotask(updatePasswordFeedback));
$('#forgot-password').addEventListener('click',async()=>{if(!supabase)return;const email=$('#auth-form').elements.email.value.trim(),button=$('#forgot-password');if(!email){showAuthMessage('Skriv inn e-postadressen din først.',true);$('#auth-form').elements.email.focus();return;}button.disabled=true;showAuthMessage('');try{const redirectTo=`${location.origin}${location.pathname}`;const {error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo});if(error)throw error;showAuthMessage('Hvis adressen er registrert, får du en e-post med lenke for å velge nytt passord.');}catch(error){showAuthMessage(authErrorMessage(error),true);}finally{button.disabled=false;}});
$('#resend-confirmation').addEventListener('click',async()=>{if(!supabase)return;const form=$('#auth-form'),email=form.elements.email.value.trim(),button=$('#resend-confirmation');if(!email){showAuthMessage('Skriv inn e-postadressen din først.',true);return;}button.disabled=true;try{const redirectURL=pendingInvitationToken?invitationURL(pendingInvitationToken):location.origin,{error}=await supabase.auth.resend({type:'signup',email,options:{emailRedirectTo:redirectURL}});if(error)throw error;showAuthMessage('Hvis registreringen finnes, er en ny bekreftelsesmail sendt.');}catch(error){showAuthMessage(authErrorMessage(error),true);}finally{button.disabled=false;}});
$('#password-update-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.target,password=form.elements.password.value,confirmation=form.elements.passwordConfirm.value,message=$('#password-update-message'),submit=form.querySelector('[type="submit"]');message.hidden=true;if(password!==confirmation){message.textContent='Passordene er ikke like.';message.classList.add('error');message.hidden=false;return;}submit.disabled=true;try{const {error}=await supabase.auth.updateUser({password});if(error)throw error;closeDialog('password-update-dialog');form.reset();toast('Passordet er oppdatert. Du er nå logget inn.');}catch(error){message.textContent=authErrorMessage(error);message.classList.add('error');message.hidden=false;}finally{submit.disabled=false;}});
$('#terms-open').addEventListener('click',()=>$('#terms-dialog').showModal());
$('#privacy-open').addEventListener('click',()=>$('#privacy-dialog').showModal());
$('#delete-account-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.target,confirmation=form.elements.confirmation.value,submit=form.querySelector('[type="submit"]'),message=$('#delete-account-message');message.hidden=true;if(confirmation!=='SLETT'){message.textContent='Skriv SLETT med store bokstaver.';message.classList.add('error');message.hidden=false;return;}submit.disabled=true;try{const {error}=await supabase.functions.invoke('delete-account',{body:{confirmation}});if(error)throw error;await supabase.auth.signOut({scope:'local'});closeDialog('delete-account-dialog');if($('#profile-dialog').open)closeDialog('profile-dialog');form.reset();await applySession(null);toast('Kontoen og innholdet ditt er slettet.');}catch(error){console.error(error);message.textContent='Kontoen kunne ikke slettes. Prøv igjen.';message.classList.add('error');message.hidden=false;}finally{submit.disabled=false;}});
$('#avatar-upload').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;if(!ALLOWED_IMAGE_TYPES.has(file.type)){toast('Velg JPG, PNG, WebP eller GIF.');e.target.value='';return;}if(file.size>1.5*1024*1024){toast('Bildet er for stort. Velg et bilde under 1,5 MB.');e.target.value='';return;}if(avatarPreviewURL)URL.revokeObjectURL(avatarPreviewURL);avatarPreviewURL=URL.createObjectURL(file);pendingAvatarFile=file;removeAvatar=false;$('#avatar-preview').src=avatarPreviewURL;$('#avatar-remove').hidden=false;});
$('#avatar-remove').addEventListener('click',()=>{pendingAvatarFile=null;removeAvatar=true;if(avatarPreviewURL)URL.revokeObjectURL(avatarPreviewURL);avatarPreviewURL='';$('#avatar-upload').value='';$('#avatar-preview').src=avatarURL(USER.id||'guest');$('#avatar-remove').hidden=true;});
$('#profile-edit-form').addEventListener('submit',async e=>{e.preventDefault();if(!currentSession)return;const form=e.target,values=new FormData(form),firstName=values.get('firstName').trim(),lastName=values.get('lastName').trim(),district=values.get('district').trim(),submit=form.querySelector('[type="submit"]');if(!firstName||!lastName||!district)return;submit.disabled=true;let nextAvatarPath=removeAvatar?null:USER.avatarPath;try{if(pendingAvatarFile){const extension={"image/jpeg":'jpg',"image/png":'png',"image/webp":'webp',"image/gif":'gif'}[pendingAvatarFile.type];nextAvatarPath=`${USER.id}/avatar-${Date.now()}.${extension}`;const upload=await supabase.storage.from('avatars').upload(nextAvatarPath,pendingAvatarFile,{contentType:pendingAvatarFile.type,upsert:false});if(upload.error)throw upload.error;}const update=await supabase.from('profiles').update({first_name:firstName,last_name:lastName,district,avatar_path:nextAvatarPath}).eq('id',USER.id).select('first_name, last_name, district, avatar_path').single();if(update.error)throw update.error;const previousAvatarPath=USER.avatarPath;USER.firstName=update.data.first_name;USER.lastName=update.data.last_name;USER.district=update.data.district;USER.avatarPath=update.data.avatar_path;USER.customAvatar=publicAvatarURL(USER.avatarPath);state.events.filter(event=>event.creatorId===USER.id).forEach(event=>event.organizer=USER.name);if(previousAvatarPath&&previousAvatarPath!==USER.avatarPath)await supabase.storage.from('avatars').remove([previousAvatarPath]);updateAvatarUI();renderProfile();closeDialog('profile-edit-dialog');toast('Profilen er oppdatert.');}catch(error){console.error(error);toast('Kunne ikke lagre profilen. Prøv igjen.');}finally{submit.disabled=false;}});
$('#create-open').addEventListener('click',()=>{if(!currentSession){openAuthDialog('signup');toast('Opprett en profil for å lage arrangementer.');return;}openCreate();});
$('#event-image-upload').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;if(!ALLOWED_IMAGE_TYPES.has(file.type)){toast('Velg JPG, PNG, WebP eller GIF.');e.target.value='';return;}if(file.size>3*1024*1024){toast('Bildet er for stort. Velg et bilde under 3 MB.');e.target.value='';return;}const reader=new FileReader();reader.onload=()=>{draftEventImageFile=file;state.draftRemoveImage=false;state.draftImage=reader.result;renderEventImagePresets();$('#event-image-preview').src=state.draftImage;$('#event-image-preview').hidden=false;$('#event-image-remove').hidden=false;};reader.onerror=()=>toast('Bildet kunne ikke leses.');reader.readAsDataURL(file);});
