$('#pick-start').addEventListener('click',()=>{closeDialog('create-dialog');state.picking=true;$('.map-shell').classList.add('picking');$('#pick-bar').hidden=false;$('#pick-done').disabled=!state.draftLocation;$('#pick-instruction').textContent=state.draftLocation?'Kartpunkt er valgt. Klikk for å flytte det.':'Klikk i kartet for å plassere eventet.';if(state.draftLocation){draftMarker=L.marker(state.draftLocation,{icon:L.divIcon({className:'map-pin',html:'<div class="pin-core" style="--category:#333"><span>+</span></div>',iconSize:[30,36],iconAnchor:[15,33]})}).addTo(map);}if(innerWidth<=720)setMobileView('map');$('#pick-cancel').focus();});
