$('#event-form').addEventListener('submit',async e=>{
 e.preventDefault();const form=e.target,values=new FormData(form),title=values.get('title').trim(),description=values.get('description').trim(),venue=values.get('venue').trim();
 if(!title||!description){toast('Fyll inn tittel og beskrivelse.');return;}
 if(!venue&&!state.draftLocation){toast('Skriv et stedsnavn eller velg et punkt i kartet.');$('#venue-input').focus();return;}
 const endDate=values.get('end')<=values.get('start')?plusDays(values.get('date'),1):values.get('date');
 const location=state.draftLocation||{lat:CENTER[0],lng:CENTER[1]};
 const preset=state.draftImagePreset||EVENT_IMAGES.find(image=>image.src===state.draftImage)?.id||'green',submit=form.querySelector('[type="submit"]'),editingId=state.editingEventId,visibility=values.get('visibility'),registrationType=visibility==='public'?values.get('registrationType'):'internal',externalRegistrationUrl=registrationType==='external'?values.get('externalRegistrationUrl').trim():null,capacityValue=values.get('capacity').trim(),capacity=visibility==='public'&&registrationType==='internal'&&capacityValue?Number(capacityValue):null;submit.disabled=true;let eventId=editingId||crypto.randomUUID(),imageWarning=false,newImagePath=null;
 if(registrationType==='external'&&(!externalRegistrationUrl||!externalRegistrationUrl.startsWith('https://'))){toast('Legg inn en gyldig påmeldingslenke som starter med https://');form.elements.externalRegistrationUrl.focus();submit.disabled=false;return;}
 const payload={title,description,category:values.get('category'),starts_at:localDateTimeISO(values.get('date'),values.get('start')),ends_at:localDateTimeISO(endDate,values.get('end')),venue:venue||'Valgt sted i Oslo',latitude:location.lat,longitude:location.lng,price_text:values.get('price').trim()||'Gratis',visibility,capacity,registration_type:registrationType,external_registration_url:externalRegistrationUrl,status:'published',image_preset:preset};
 try{
  if(!editingId){const insert=await supabase.from('events').insert({id:eventId,creator_id:USER.id,...payload});if(insert.error)throw insert.error;}
  if(draftEventImageFile){const extension={"image/jpeg":'jpg',"image/png":'png',"image/webp":'webp',"image/gif":'gif'}[draftEventImageFile.type];newImagePath=`${eventId}/event-${Date.now()}.${extension}`;const upload=await supabase.storage.from('event-images').upload(newImagePath,draftEventImageFile,{contentType:draftEventImageFile.type,upsert:false});if(upload.error){if(editingId)throw upload.error;imageWarning=true;newImagePath=null;}}
  if(editingId){const nextImagePath=newImagePath||(state.draftRemoveImage?null:state.draftExistingImagePath);const update=await supabase.from('events').update({...payload,image_path:nextImagePath}).eq('id',editingId);if(update.error)throw update.error;if(state.draftExistingImagePath&&state.draftExistingImagePath!==nextImagePath)await supabase.storage.from('event-images').remove([state.draftExistingImagePath]);}
  else if(newImagePath){const update=await supabase.from('events').update({image_path:newImagePath}).eq('id',eventId);if(update.error){await supabase.storage.from('event-images').remove([newImagePath]);imageWarning=true;}}
  await loadEvents();const event=state.events.find(item=>item.id===eventId);closeDialog('create-dialog');if(event)revealEvent(event);toast(editingId?'Arrangementet er oppdatert.':imageWarning?'Arrangementet ble lagret, men bildet kunne ikke lastes opp.':'Arrangementet er opprettet og lagret.');
 }catch(error){console.error(error);if(newImagePath)await supabase.storage.from('event-images').remove([newImagePath]);toast(`${editingId?'Kunne ikke oppdatere':'Kunne ikke opprette'}: ${eventErrorMessage(error)}`);}finally{submit.disabled=false;}
});
